<?php require_once __DIR__.'/includes/init.php'; if(!empty($_SESSION['user'])){header('Location:dashboard.php');exit;} $err=''; if($_SERVER['REQUEST_METHOD']==='POST'){checkCsrf();$st=db()->prepare('SELECT u.*,c.name_en company_name FROM users u LEFT JOIN companies c ON c.id=u.company_id WHERE u.email=? AND u.active=1 LIMIT 1');$st->execute([trim($_POST['email'])]);$u=$st->fetch();if($u&&password_verify($_POST['password'],$u['password'])){$_SESSION['user']=$u;audit('login','user',$u['id']);header('Location:dashboard.php');exit;}$err='Invalid email or password';} ?>
<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><link rel="stylesheet" href="assets/css/app.css"><title>Login</title></head><body class="login-page"><form class="login-card" method="post"><h1>🏢 <?=t('system')?></h1><p>Secure access for administrators and company managers</p><?php if($err):?><div class="alert danger"><?=e($err)?></div><?php endif;?><input type="hidden" name="csrf" value="<?=csrf()?>"><label><?=t('email')?></label><input name="email" type="email" required><label><?=t('password')?></label><input name="password" type="password" required><button class="btn primary"><?=t('login')?></button><div class="hint">Demo: admin@example.com / Admin@123</div></form></body></html>
